// also include diagrams where the Z is attached to b-bbar line
// notation: (qqb hel, bbb hel, outgoing lepton helicity is left-handed
void ampqqb_qqb(int i1, int i2, int i5, int i6, FArray3D<std::complex<double>>& qqbA, FArray3D<std::complex<double>>& qqbB) {
  int j, k;
  int three = 3, four = 4;
  const FArray1D<int> swap({2,1}, 2);

  // Z to qqb, L L L
  qqbA(1,1,1) = +aqqb_zbb_new_(&i1,&i6,&i5,&i2,&three,&four); // @coverage-probe
  // Z to bbb, L L
  qqbB(1,1,1) = +aqqb_zbb_new_(&i6,&i1,&i2,&i5,&three,&four);

  // Z to qqb, R R
  qqbA(2,2,1) = -aqqb_zbb_new_(&i2,&i5,&i6,&i1,&three,&four);
  // Z to bbb, R R
  qqbB(2,2,1) = -aqqb_zbb_new_(&i5,&i2,&i1,&i6,&three,&four);

  // Z to qqb, L R
  qqbA(1,2,1) = +aqqb_zbb_new_(&i1,&i5,&i6,&i2,&three,&four);
  // Z to bbb, L R
  qqbB(1,2,1) = -aqqb_zbb_new_(&i5,&i1,&i2,&i6,&three,&four);

  // Z to qqb, R L
  qqbA(2,1,1) = -aqqb_zbb_new_(&i2,&i6,&i5,&i1,&three,&four);
  // Z to bbb, R L
  qqbB(2,1,1) = +aqqb_zbb_new_(&i6,&i2,&i1,&i5,&three,&four);

  for (j = 1; j <= 2; j++) {
    for (k = 1; k <= 2; k++) {
      qqbA(j,k,2) = std::conj(qqbA(swap(j), swap(k), 1));
      qqbB(j,k,2) = std::conj(qqbB(swap(j), swap(k), 1));
    }
  }
  return;
}

extern "C" {
  void ampqqb_qqb_wrapper(int i1, int i2, int i5, int i6, std::complex<double>* fqqbA, std::complex<double>* fqqbB) {
    FArray3D<std::complex<double>> qqbA(fqqbA, 2, 2, 2);
    FArray3D<std::complex<double>> qqbB(fqqbB, 2, 2, 2);
    ampqqb_qqb(i1, i2, i5, i6, qqbA, qqbB);
  }
}

