#include <msq_z2jetx.hpp>

#include <complex>
#include <constants_mod.hpp>
#include <ewcharge_mod.hpp>
#include <FArray.hpp>
#include <nf_mod.hpp>
#include <zcouple_cms_mod.hpp>
#include <zcouple_mod.hpp>

void msq_qq(int ja, int ka,
            FArray3D<std::complex<double>>& amp1_a, FArray3D<std::complex<double>>& amp1_b,
            FArray3D<std::complex<double>>& amp2_a, FArray3D<std::complex<double>>& amp2_b,
            std::complex<double> prop,
            double& msq0, double& msq1, double& msq2) {
  using namespace constants_mod;
  using namespace nf_mod;
  using namespace ewcharge_mod;
  using namespace zcouple_mod;
  using namespace zcouple_cms_mod;

  std::complex<double> a111, a112, a121, a211, a122, a212, a221, a222;
  std::complex<double> b111, b112, b121, b211, b122, b212, b221, b222;

  if (ja != ka) {
    a111 = (Q(ja)*q1+zl(ja)*zl1*prop)*amp1_a(1,1,1)
         + (Q(ka)*q1+zl(ka)*zl1*prop)*amp1_b(1,1,1);
    a121 = (Q(ja)*q1+zl(ja)*zl1*prop)*amp1_a(1,2,1)
         + (Q(ka)*q1+zr(ka)*zl1*prop)*amp1_b(1,2,1);
    a112 = (Q(ja)*q1+zl(ja)*zr1*prop)*amp1_a(1,1,2)
         + (Q(ka)*q1+zl(ka)*zr1*prop)*amp1_b(1,1,2);
    a122 = (Q(ja)*q1+zl(ja)*zr1*prop)*amp1_a(1,2,2)
         + (Q(ka)*q1+zr(ka)*zr1*prop)*amp1_b(1,2,2);
    a211 = (Q(ja)*q1+zr(ja)*zl1*prop)*amp1_a(2,1,1)
         + (Q(ka)*q1+zl(ka)*zl1*prop)*amp1_b(2,1,1);
    a221 = (Q(ja)*q1+zr(ja)*zl1*prop)*amp1_a(2,2,1)
         + (Q(ka)*q1+zr(ka)*zl1*prop)*amp1_b(2,2,1);
    a212 = (Q(ja)*q1+zr(ja)*zr1*prop)*amp1_a(2,1,2)
         + (Q(ka)*q1+zl(ka)*zr1*prop)*amp1_b(2,1,2);
    a222 = (Q(ja)*q1+zr(ja)*zr1*prop)*amp1_a(2,2,2)
         + (Q(ka)*q1+zr(ka)*zr1*prop)*amp1_b(2,2,2);

    msq0 = zip;
    msq1 = std::real(a111*std::conj(a111))+std::real(a112*std::conj(a112))
         + std::real(a221*std::conj(a221))+std::real(a222*std::conj(a222))
         + std::real(a122*std::conj(a122))+std::real(a212*std::conj(a212))
         + std::real(a121*std::conj(a121))+std::real(a211*std::conj(a211));
    msq2 = zip;

  } else if (ja == ka) {
    a111 = (Q(ja)*q1+zl(ja)*zl1*prop)*(amp1_a(1,1,1)+amp1_b(1,1,1));
    b111 = (Q(ja)*q1+zl(ja)*zl1*prop)*(amp2_a(1,1,1)+amp2_b(1,1,1));
    a112 = (Q(ja)*q1+zl(ja)*zr1*prop)*(amp1_a(1,1,2)+amp1_b(1,1,2));
    b112 = (Q(ja)*q1+zl(ja)*zr1*prop)*(amp2_a(1,1,2)+amp2_b(1,1,2));
    a221 = (Q(ja)*q1+zr(ja)*zl1*prop)*(amp1_a(2,2,1)+amp1_b(2,2,1));
    b221 = (Q(ja)*q1+zr(ja)*zl1*prop)*(amp2_a(2,2,1)+amp2_b(2,2,1));
    a222 = (Q(ja)*q1+zr(ja)*zr1*prop)*(amp1_a(2,2,2)+amp1_b(2,2,2));
    b222 = (Q(ja)*q1+zr(ja)*zr1*prop)*(amp2_a(2,2,2)+amp2_b(2,2,2));

    a121 = (Q(ja)*q1+zl(ja)*zl1*prop)*amp1_a(1,2,1)
         + (Q(ka)*q1+zr(ka)*zl1*prop)*amp1_b(1,2,1);
    b121 = (Q(ja)*q1+zl(ja)*zl1*prop)*amp2_a(1,2,1)
         + (Q(ka)*q1+zr(ka)*zl1*prop)*amp2_b(1,2,1);
    a122 = (Q(ja)*q1+zl(ja)*zr1*prop)*amp1_a(1,2,2)
         + (Q(ka)*q1+zr(ka)*zr1*prop)*amp1_b(1,2,2);
    b122 = (Q(ja)*q1+zl(ja)*zr1*prop)*amp2_a(1,2,2)
         + (Q(ka)*q1+zr(ka)*zr1*prop)*amp2_b(1,2,2);
    a211 = (Q(ja)*q1+zr(ja)*zl1*prop)*amp1_a(2,1,1)
         + (Q(ka)*q1+zl(ka)*zl1*prop)*amp1_b(2,1,1);
    b211 = (Q(ja)*q1+zr(ja)*zl1*prop)*amp2_a(2,1,1)
         + (Q(ka)*q1+zl(ka)*zl1*prop)*amp2_b(2,1,1);
    a212 = (Q(ja)*q1+zr(ja)*zr1*prop)*amp1_a(2,1,2)
         + (Q(ka)*q1+zl(ka)*zr1*prop)*amp1_b(2,1,2);
    b212 = (Q(ja)*q1+zr(ja)*zr1*prop)*amp2_a(2,1,2)
         + (Q(ka)*q1+zl(ka)*zr1*prop)*amp2_b(2,1,2);

    msq0 = half*(std::real(a111*std::conj(b111))+std::real(a112*std::conj(b112))
               + std::real(a221*std::conj(b221))+std::real(a222*std::conj(b222)))*two/xn;
    msq1 = half*(std::real(a111*std::conj(a111))+std::real(a112*std::conj(a112))
               + std::real(a221*std::conj(a221))+std::real(a222*std::conj(a222))
               + std::real(a122*std::conj(a122))+std::real(a212*std::conj(a212))
               + std::real(a121*std::conj(a121))+std::real(a211*std::conj(a211)));
    msq2 = half*(std::real(b111*std::conj(b111))+std::real(b112*std::conj(b112))
               + std::real(b221*std::conj(b221))+std::real(b222*std::conj(b222))
               + std::real(b122*std::conj(b122))+std::real(b212*std::conj(b212))
               + std::real(b121*std::conj(b121))+std::real(b211*std::conj(b211)));
  }

  return;
}

void msq_qqb(int ja, int ka,
             FArray3D<std::complex<double>>& amp1_a, FArray3D<std::complex<double>>& amp1_b,
             FArray3D<std::complex<double>>& amp2_a, FArray3D<std::complex<double>>& amp2_b,
             std::complex<double> prop,
             double& msq0, double& msq1, double& msq2,
             double& msq_up, double& msq_down) {
  using namespace constants_mod;
  using namespace nf_mod;
  using namespace ewcharge_mod;
  using namespace zcouple_mod;
  using namespace zcouple_cms_mod;

  std::complex<double> a111, a112, a121, a211, a122, a212, a221, a222;
  std::complex<double> b111, b112, b121, b211, b122, b212, b221, b222;

  if (ja != -ka) {
    a111 = (Q(+ja)*q1+zl(+ja)*zl1*prop)*amp1_a(1,1,1)
         + (Q(-ka)*q1+zl(-ka)*zl1*prop)*amp1_b(1,1,1);
    a112 = (Q(+ja)*q1+zl(+ja)*zr1*prop)*amp1_a(1,1,2)
         + (Q(-ka)*q1+zl(-ka)*zr1*prop)*amp1_b(1,1,2);
    a221 = (Q(+ja)*q1+zr(+ja)*zl1*prop)*amp1_a(2,2,1)
         + (Q(-ka)*q1+zr(-ka)*zl1*prop)*amp1_b(2,2,1);
    a222 = (Q(+ja)*q1+zr(+ja)*zr1*prop)*amp1_a(2,2,2)
         + (Q(-ka)*q1+zr(-ka)*zr1*prop)*amp1_b(2,2,2);

    a121 = (Q(+ja)*q1+zl(+ja)*zl1*prop)*amp1_a(1,2,1)
         + (Q(-ka)*q1+zr(-ka)*zl1*prop)*amp1_b(1,2,1);
    a122 = (Q(+ja)*q1+zl(+ja)*zr1*prop)*amp1_a(1,2,2)
         + (Q(-ka)*q1+zr(-ka)*zr1*prop)*amp1_b(1,2,2);
    a211 = (Q(+ja)*q1+zr(+ja)*zl1*prop)*amp1_a(2,1,1)
         + (Q(-ka)*q1+zl(-ka)*zl1*prop)*amp1_b(2,1,1);
    a212 = (Q(+ja)*q1+zr(+ja)*zr1*prop)*amp1_a(2,1,2)
         + (Q(-ka)*q1+zl(-ka)*zr1*prop)*amp1_b(2,1,2);

    msq0 = zip;
    msq1 = zip;
    msq2 = std::real(a111*std::conj(a111))+std::real(a112*std::conj(a112))
         + std::real(a221*std::conj(a221))+std::real(a222*std::conj(a222))
         + std::real(a122*std::conj(a122))+std::real(a212*std::conj(a212))
         + std::real(a121*std::conj(a121))+std::real(a211*std::conj(a211));

    msq_up = 0.0;
    msq_down = 0.0;

  } else if (ja == -ka) {
    // case where final state from annihilation diagrams is the same quark
    a111 = (Q(ja)*q1+zl(ja)*zl1*prop)*(amp1_a(1,1,1)+amp1_b(1,1,1));
    b111 = (Q(ja)*q1+zl(ja)*zl1*prop)*(amp2_a(1,1,1)+amp2_b(1,1,1));

    a112 = (Q(ja)*q1+zl(ja)*zr1*prop)*(amp1_a(1,1,2)+amp1_b(1,1,2));
    b112 = (Q(ja)*q1+zl(ja)*zr1*prop)*(amp2_a(1,1,2)+amp2_b(1,1,2));

    a221 = (Q(ja)*q1+zr(ja)*zl1*prop)*(amp1_a(2,2,1)+amp1_b(2,2,1));
    b221 = (Q(ja)*q1+zr(ja)*zl1*prop)*(amp2_a(2,2,1)+amp2_b(2,2,1));

    a222 = (Q(ja)*q1+zr(ja)*zr1*prop)*(amp1_a(2,2,2)+amp1_b(2,2,2));
    b222 = (Q(ja)*q1+zr(ja)*zr1*prop)*(amp2_a(2,2,2)+amp2_b(2,2,2));

    a121 = (Q(+ja)*q1+zl(+ja)*zl1*prop)*amp1_a(1,2,1)
         + (Q(-ka)*q1+zr(-ka)*zl1*prop)*amp1_b(1,2,1);
    a122 = (Q(+ja)*q1+zl(+ja)*zr1*prop)*amp1_a(1,2,2)
         + (Q(-ka)*q1+zr(-ka)*zr1*prop)*amp1_b(1,2,2);
    a211 = (Q(+ja)*q1+zr(+ja)*zl1*prop)*amp1_a(2,1,1)
         + (Q(-ka)*q1+zl(-ka)*zl1*prop)*amp1_b(2,1,1);
    a212 = (Q(+ja)*q1+zr(+ja)*zr1*prop)*amp1_a(2,1,2)
         + (Q(-ka)*q1+zl(-ka)*zr1*prop)*amp1_b(2,1,2);

    b121 = (Q(+ja)*q1+zl(+ja)*zl1*prop)*amp2_a(1,2,1)
         + (Q(-ka)*q1+zr(-ka)*zl1*prop)*amp2_b(1,2,1);
    b122 = (Q(+ja)*q1+zl(+ja)*zr1*prop)*amp2_a(1,2,2)
         + (Q(-ka)*q1+zr(-ka)*zr1*prop)*amp2_b(1,2,2);
    b211 = (Q(+ja)*q1+zr(+ja)*zl1*prop)*amp2_a(2,1,1)
         + (Q(-ka)*q1+zl(-ka)*zl1*prop)*amp2_b(2,1,1);
    b212 = (Q(+ja)*q1+zr(+ja)*zr1*prop)*amp2_a(2,1,2)
         + (Q(-ka)*q1+zl(-ka)*zr1*prop)*amp2_b(2,1,2);

    msq0 = (std::real(a111*std::conj(b111))+std::real(a112*std::conj(b112))
          + std::real(a221*std::conj(b221))+std::real(a222*std::conj(b222)))*two/xn; // @coverage-probe
    msq1 = std::real(b111*std::conj(b111))+std::real(b112*std::conj(b112))
         + std::real(b221*std::conj(b221))+std::real(b222*std::conj(b222))
         + std::real(b122*std::conj(b122))+std::real(b212*std::conj(b212))
         + std::real(b121*std::conj(b121))+std::real(b211*std::conj(b211));
    msq2 = std::real(a111*std::conj(a111))+std::real(a112*std::conj(a112))
         + std::real(a221*std::conj(a221))+std::real(a222*std::conj(a222))
         + std::real(a122*std::conj(a122))+std::real(a212*std::conj(a212))
         + std::real(a121*std::conj(a121))+std::real(a211*std::conj(a211));

    b111 = (Q(+ja)*q1+zl(+ja)*zl1*prop)*amp2_a(1,1,1)
         + (Q(+1)*q1+zl(+1)*zl1*prop)*amp2_b(1,1,1);
    b112 = (Q(+ja)*q1+zl(+ja)*zr1*prop)*amp2_a(1,1,2)
         + (Q(+1)*q1+zl(+1)*zr1*prop)*amp2_b(1,1,2);
    b221 = (Q(+ja)*q1+zr(+ja)*zl1*prop)*amp2_a(2,2,1)
         + (Q(+1)*q1+zr(+1)*zl1*prop)*amp2_b(2,2,1);
    b222 = (Q(+ja)*q1+zr(+ja)*zr1*prop)*amp2_a(2,2,2)
         + (Q(+1)*q1+zr(+1)*zr1*prop)*amp2_b(2,2,2);
    b121 = (Q(+ja)*q1+zl(+ja)*zl1*prop)*amp2_a(1,2,1)
         + (Q(+1)*q1+zr(+1)*zl1*prop)*amp2_b(1,2,1);
    b122 = (Q(+ja)*q1+zl(+ja)*zr1*prop)*amp2_a(1,2,2)
         + (Q(+1)*q1+zr(+1)*zr1*prop)*amp2_b(1,2,2);
    b211 = (Q(+ja)*q1+zr(+ja)*zl1*prop)*amp2_a(2,1,1)
         + (Q(+1)*q1+zl(+1)*zl1*prop)*amp2_b(2,1,1);
    b212 = (Q(+ja)*q1+zr(+ja)*zr1*prop)*amp2_a(2,1,2)
         + (Q(+1)*q1+zl(+1)*zr1*prop)*amp2_b(2,1,2);

    msq_down = std::real(b111*std::conj(b111))+std::real(b112*std::conj(b112))
             + std::real(b221*std::conj(b221))+std::real(b222*std::conj(b222))
             + std::real(b122*std::conj(b122))+std::real(b212*std::conj(b212))
             + std::real(b121*std::conj(b121))+std::real(b211*std::conj(b211));

    b111 = (Q(+ja)*q1+zl(+ja)*zl1*prop)*amp2_a(1,1,1)
         + (Q(+2)*q1+zl(+2)*zl1*prop)*amp2_b(1,1,1);
    b112 = (Q(+ja)*q1+zl(+ja)*zr1*prop)*amp2_a(1,1,2)
         + (Q(+2)*q1+zl(+2)*zr1*prop)*amp2_b(1,1,2);
    b221 = (Q(+ja)*q1+zr(+ja)*zl1*prop)*amp2_a(2,2,1)
         + (Q(+2)*q1+zr(+2)*zl1*prop)*amp2_b(2,2,1);
    b222 = (Q(+ja)*q1+zr(+ja)*zr1*prop)*amp2_a(2,2,2)
         + (Q(+2)*q1+zr(+2)*zr1*prop)*amp2_b(2,2,2);
    b121 = (Q(+ja)*q1+zl(+ja)*zl1*prop)*amp2_a(1,2,1)
         + (Q(+2)*q1+zr(+2)*zl1*prop)*amp2_b(1,2,1);
    b122 = (Q(+ja)*q1+zl(+ja)*zr1*prop)*amp2_a(1,2,2)
         + (Q(+2)*q1+zr(+2)*zr1*prop)*amp2_b(1,2,2);
    b211 = (Q(+ja)*q1+zr(+ja)*zl1*prop)*amp2_a(2,1,1)
         + (Q(+2)*q1+zl(+2)*zl1*prop)*amp2_b(2,1,1);
    b212 = (Q(+ja)*q1+zr(+ja)*zr1*prop)*amp2_a(2,1,2)
         + (Q(+2)*q1+zl(+2)*zr1*prop)*amp2_b(2,1,2);

    msq_up = std::real(b111*std::conj(b111))+std::real(b112*std::conj(b112))
           + std::real(b221*std::conj(b221))+std::real(b222*std::conj(b222))
           + std::real(b122*std::conj(b122))+std::real(b212*std::conj(b212))
           + std::real(b121*std::conj(b121))+std::real(b211*std::conj(b211));
  }

  return;
}

extern "C" {
  void msq_qq_wrapper(int ja, int ka,
                       std::complex<double>* amp1_a, std::complex<double>* amp1_b,
                       std::complex<double>* amp2_a, std::complex<double>* amp2_b,
                       std::complex<double> prop,
                       double* msq0, double* msq1, double* msq2) {
    FArray3D<std::complex<double>> famp1_a(amp1_a, 2, 2, 2);
    FArray3D<std::complex<double>> famp1_b(amp1_b, 2, 2, 2);
    FArray3D<std::complex<double>> famp2_a(amp2_a, 2, 2, 2);
    FArray3D<std::complex<double>> famp2_b(amp2_b, 2, 2, 2);
    msq_qq(ja, ka, famp1_a, famp1_b, famp2_a, famp2_b, prop, *msq0, *msq1, *msq2);
  }

  void msq_qqb_wrapper(int ja, int ka,
                        std::complex<double>* amp1_a, std::complex<double>* amp1_b,
                        std::complex<double>* amp2_a, std::complex<double>* amp2_b,
                        std::complex<double> prop,
                        double* msq0, double* msq1, double* msq2,
                        double* msq_up, double* msq_down) {
    FArray3D<std::complex<double>> famp1_a(amp1_a, 2, 2, 2);
    FArray3D<std::complex<double>> famp1_b(amp1_b, 2, 2, 2);
    FArray3D<std::complex<double>> famp2_a(amp2_a, 2, 2, 2);
    FArray3D<std::complex<double>> famp2_b(amp2_b, 2, 2, 2);
    msq_qqb(ja, ka, famp1_a, famp1_b, famp2_a, famp2_b, prop, *msq0, *msq1, *msq2, *msq_up, *msq_down);
  }
}

