48	    msq0 = zip;
49	    msq1 = std::real(a111*std::conj(a111))+std::real(a112*std::conj(a112))
50	         + std::real(a221*std::conj(a221))+std::real(a222*std::conj(a222))
51	         + std::real(a122*std::conj(a122))+std::real(a212*std::conj(a212))
52	         + std::real(a121*std::conj(a121))+std::real(a211*std::conj(a211));
53	    msq2 = zip;
54	
55	  } else if (ja == ka) {
56	    a111 = (Q(ja)*q1+zl(ja)*zl1*prop)*(amp1_a(1,1,1)+amp1_b(1,1,1));
57	    b111 = (Q(ja)*q1+zl(ja)*zl1*prop)*(amp2_a(1,1,1)+amp2_b(1,1,1));
58	    a112 = (Q(ja)*q1+zl(ja)*zr1*prop)*(amp1_a(1,1,2)+amp1_b(1,1,2));
59	    b112 = (Q(ja)*q1+zl(ja)*zr1*prop)*(amp2_a(1,1,2)+amp2_b(1,1,2));
60	    a221 = (Q(ja)*q1+zr(ja)*zl1*prop)*(amp1_a(2,2,1)+amp1_b(2,2,1));
61	    b221 = (Q(ja)*q1+zr(ja)*zl1*prop)*(amp2_a(2,2,1)+amp2_b(2,2,1));
62	    a222 = (Q(ja)*q1+zr(ja)*zr1*prop)*(amp1_a(2,2,2)+amp1_b(2,2,2));
63	    b222 = (Q(ja)*q1+zr(ja)*zr1*prop)*(amp2_a(2,2,2)+amp2_b(2,2,2));
64	
65	    a121 = (Q(ja)*q1+zl(ja)*zl1*prop)*amp1_a(1,2,1)
66	         + (Q(ka)*q1+zr(ka)*zl1*prop)*amp1_b(1,2,1);
67	    b121 = (Q(ja)*q1+zl(ja)*zl1*prop)*amp2_a(1,2,1)
68	         + (Q(ka)*q1+zr(ka)*zl1*prop)*amp2_b(1,2,1);
69	    a122 = (Q(ja)*q1+zl(ja)*zr1*prop)*amp1_a(1,2,2)
70	         + (Q(ka)*q1+zr(ka)*zr1*prop)*amp1_b(1,2,2);
71	    b122 = (Q(ja)*q1+zl(ja)*zr1*prop)*amp2_a(1,2,2)
72	         + (Q(ka)*q1+zr(ka)*zr1*prop)*amp2_b(1,2,2);
73	    a211 = (Q(ja)*q1+zr(ja)*zl1*prop)*amp1_a(2,1,1)
74	         + (Q(ka)*q1+zl(ka)*zl1*prop)*amp1_b(2,1,1);
75	    b211 = (Q(ja)*q1+zr(ja)*zl1*prop)*amp2_a(2,1,1)
76	         + (Q(ka)*q1+zl(ka)*zl1*prop)*amp2_b(2,1,1);
77	    a212 = (Q(ja)*q1+zr(ja)*zr1*prop)*amp1_a(2,1,2)
78	         + (Q(ka)*q1+zl(ka)*zr1*prop)*amp1_b(2,1,2);
79	    b212 = (Q(ja)*q1+zr(ja)*zr1*prop)*amp2_a(2,1,2)
80	         + (Q(ka)*q1+zl(ka)*zr1*prop)*amp2_b(2,1,2);
81	
82	    msq0 = half*(std::real(a111*std::conj(b111))+std::real(a112*std::conj(b112))
83	               + std::real(a221*std::conj(b221))+std::real(a222*std::conj(b222)))*two/xn;
84	    msq1 = half*(std::real(a111*std::conj(a111))+std::real(a112*std::conj(a112))
85	               + std::real(a221*std::conj(a221))+std::real(a222*std::conj(a222))
86	               + std::real(a122*std::conj(a122))+std::real(a212*std::conj(a212))
87	               + std::real(a121*std::conj(a121))+std::real(a211*std::conj(a211)));
88	    msq2 = half*(std::real(b111*std::conj(b111))+std::real(b112*std::conj(b112))
89	               + std::real(b221*std::conj(b221))+std::real(b222*std::conj(b222))
90	               + std::real(b122*std::conj(b122))+std::real(b212*std::conj(b212))
91	               + std::real(b121*std::conj(b121))+std::real(b211*std::conj(b211)));
92	  }
93	
94	  return;
95	}
