97	void msq_qqb(int ja, int ka,
98	             FArray3D<std::complex<double>>& amp1_a, FArray3D<std::complex<double>>& amp1_b,
99	             FArray3D<std::complex<double>>& amp2_a, FArray3D<std::complex<double>>& amp2_b,
100	             std::complex<double> prop,
101	             double& msq0, double& msq1, double& msq2,
102	             double& msq_up, double& msq_down) {
103	  using namespace constants_mod;
104	  using namespace nf_mod;
105	  using namespace ewcharge_mod;
106	  using namespace zcouple_mod;
107	  using namespace zcouple_cms_mod;
108	
109	  std::complex<double> a111, a112, a121, a211, a122, a212, a221, a222;
110	  std::complex<double> b111, b112, b121, b211, b122, b212, b221, b222;
111	
112	  if (ja != -ka) {
113	    a111 = (Q(+ja)*q1+zl(+ja)*zl1*prop)*amp1_a(1,1,1)
114	         + (Q(-ka)*q1+zl(-ka)*zl1*prop)*amp1_b(1,1,1);
115	    a112 = (Q(+ja)*q1+zl(+ja)*zr1*prop)*amp1_a(1,1,2)
116	         + (Q(-ka)*q1+zl(-ka)*zr1*prop)*amp1_b(1,1,2);
117	    a221 = (Q(+ja)*q1+zr(+ja)*zl1*prop)*amp1_a(2,2,1)
118	         + (Q(-ka)*q1+zr(-ka)*zl1*prop)*amp1_b(2,2,1);
119	    a222 = (Q(+ja)*q1+zr(+ja)*zr1*prop)*amp1_a(2,2,2)
120	         + (Q(-ka)*q1+zr(-ka)*zr1*prop)*amp1_b(2,2,2);
121	
122	    a121 = (Q(+ja)*q1+zl(+ja)*zl1*prop)*amp1_a(1,2,1)
123	         + (Q(-ka)*q1+zr(-ka)*zl1*prop)*amp1_b(1,2,1);
124	    a122 = (Q(+ja)*q1+zl(+ja)*zr1*prop)*amp1_a(1,2,2)
125	         + (Q(-ka)*q1+zr(-ka)*zr1*prop)*amp1_b(1,2,2);
126	    a211 = (Q(+ja)*q1+zr(+ja)*zl1*prop)*amp1_a(2,1,1)
127	         + (Q(-ka)*q1+zl(-ka)*zl1*prop)*amp1_b(2,1,1);
128	    a212 = (Q(+ja)*q1+zr(+ja)*zr1*prop)*amp1_a(2,1,2)
129	         + (Q(-ka)*q1+zl(-ka)*zr1*prop)*amp1_b(2,1,2);
130	
131	    msq0 = zip;
132	    msq1 = zip;
133	    msq2 = std::real(a111*std::conj(a111))+std::real(a112*std::conj(a112))
134	         + std::real(a221*std::conj(a221))+std::real(a222*std::conj(a222))
135	         + std::real(a122*std::conj(a122))+std::real(a212*std::conj(a212))
136	         + std::real(a121*std::conj(a121))+std::real(a211*std::conj(a211));
137	
138	    msq_up = 0.0;
139	    msq_down = 0.0;
140	
141	  } else if (ja == -ka) {
142	    // case where final state from annihilation diagrams is the same quark
143	    a111 = (Q(ja)*q1+zl(ja)*zl1*prop)*(amp1_a(1,1,1)+amp1_b(1,1,1));
144	    b111 = (Q(ja)*q1+zl(ja)*zl1*prop)*(amp2_a(1,1,1)+amp2_b(1,1,1));
145	
146	    a112 = (Q(ja)*q1+zl(ja)*zr1*prop)*(amp1_a(1,1,2)+amp1_b(1,1,2));
147	    b112 = (Q(ja)*q1+zl(ja)*zr1*prop)*(amp2_a(1,1,2)+amp2_b(1,1,2));
148	
149	    a221 = (Q(ja)*q1+zr(ja)*zl1*prop)*(amp1_a(2,2,1)+amp1_b(2,2,1));
150	    b221 = (Q(ja)*q1+zr(ja)*zl1*prop)*(amp2_a(2,2,1)+amp2_b(2,2,1));
151	
152	    a222 = (Q(ja)*q1+zr(ja)*zr1*prop)*(amp1_a(2,2,2)+amp1_b(2,2,2));
153	    b222 = (Q(ja)*q1+zr(ja)*zr1*prop)*(amp2_a(2,2,2)+amp2_b(2,2,2));
154	
155	    a121 = (Q(+ja)*q1+zl(+ja)*zl1*prop)*amp1_a(1,2,1)
156	         + (Q(-ka)*q1+zr(-ka)*zl1*prop)*amp1_b(1,2,1);
157	    a122 = (Q(+ja)*q1+zl(+ja)*zr1*prop)*amp1_a(1,2,2)
158	         + (Q(-ka)*q1+zr(-ka)*zr1*prop)*amp1_b(1,2,2);
159	    a211 = (Q(+ja)*q1+zr(+ja)*zl1*prop)*amp1_a(2,1,1)
160	         + (Q(-ka)*q1+zl(-ka)*zl1*prop)*amp1_b(2,1,1);
161	    a212 = (Q(+ja)*q1+zr(+ja)*zr1*prop)*amp1_a(2,1,2)
162	         + (Q(-ka)*q1+zl(-ka)*zr1*prop)*amp1_b(2,1,2);
163	
164	    b121 = (Q(+ja)*q1+zl(+ja)*zl1*prop)*amp2_a(1,2,1)
165	         + (Q(-ka)*q1+zr(-ka)*zl1*prop)*amp2_b(1,2,1);
166	    b122 = (Q(+ja)*q1+zl(+ja)*zr1*prop)*amp2_a(1,2,2)
167	         + (Q(-ka)*q1+zr(-ka)*zr1*prop)*amp2_b(1,2,2);
168	    b211 = (Q(+ja)*q1+zr(+ja)*zl1*prop)*amp2_a(2,1,1)
169	         + (Q(-ka)*q1+zl(-ka)*zl1*prop)*amp2_b(2,1,1);
170	    b212 = (Q(+ja)*q1+zr(+ja)*zr1*prop)*amp2_a(2,1,2)
171	         + (Q(-ka)*q1+zl(-ka)*zr1*prop)*amp2_b(2,1,2);
172	
173	    msq0 = (std::real(a111*std::conj(b111))+std::real(a112*std::conj(b112))+std::real(a221*std::conj(b221))+std::real(a222*std::conj(b222)))*two/xn; // @coverage-probe
174	    msq1 = std::real(b111*std::conj(b111))+std::real(b112*std::conj(b112))
175	         + std::real(b221*std::conj(b221))+std::real(b222*std::conj(b222))
176	         + std::real(b122*std::conj(b122))+std::real(b212*std::conj(b212))
177	         + std::real(b121*std::conj(b121))+std::real(b211*std::conj(b211));
178	    msq2 = std::real(a111*std::conj(a111))+std::real(a112*std::conj(a112))
179	         + std::real(a221*std::conj(a221))+std::real(a222*std::conj(a222))
180	         + std::real(a122*std::conj(a122))+std::real(a212*std::conj(a212))
181	         + std::real(a121*std::conj(a121))+std::real(a211*std::conj(a211));
182	
183	    b111 = (Q(+ja)*q1+zl(+ja)*zl1*prop)*amp2_a(1,1,1)
184	         + (Q(+1)*q1+zl(+1)*zl1*prop)*amp2_b(1,1,1);
185	    b112 = (Q(+ja)*q1+zl(+ja)*zr1*prop)*amp2_a(1,1,2)
186	         + (Q(+1)*q1+zl(+1)*zr1*prop)*amp2_b(1,1,2);
187	    b221 = (Q(+ja)*q1+zr(+ja)*zl1*prop)*amp2_a(2,2,1)
188	         + (Q(+1)*q1+zr(+1)*zl1*prop)*amp2_b(2,2,1);
189	    b222 = (Q(+ja)*q1+zr(+ja)*zr1*prop)*amp2_a(2,2,2)
190	         + (Q(+1)*q1+zr(+1)*zr1*prop)*amp2_b(2,2,2);
191	    b121 = (Q(+ja)*q1+zl(+ja)*zl1*prop)*amp2_a(1,2,1)
192	         + (Q(+1)*q1+zr(+1)*zl1*prop)*amp2_b(1,2,1);
193	    b122 = (Q(+ja)*q1+zl(+ja)*zr1*prop)*amp2_a(1,2,2)
194	         + (Q(+1)*q1+zr(+1)*zr1*prop)*amp2_b(1,2,2);
195	    b211 = (Q(+ja)*q1+zr(+ja)*zl1*prop)*amp2_a(2,1,1)
196	         + (Q(+1)*q1+zl(+1)*zl1*prop)*amp2_b(2,1,1);
197	    b212 = (Q(+ja)*q1+zr(+ja)*zr1*prop)*amp2_a(2,1,2)
198	         + (Q(+1)*q1+zl(+1)*zr1*prop)*amp2_b(2,1,2);
199	
200	    msq_down = std::real(b111*std::conj(b111))+std::real(b112*std::conj(b112))
201	             + std::real(b221*std::conj(b221))+std::real(b222*std::conj(b222))
202	             + std::real(b122*std::conj(b122))+std::real(b212*std::conj(b212))
203	             + std::real(b121*std::conj(b121))+std::real(b211*std::conj(b211));
204	
205	    b111 = (Q(+ja)*q1+zl(+ja)*zl1*prop)*amp2_a(1,1,1)
206	         + (Q(+2)*q1+zl(+2)*zl1*prop)*amp2_b(1,1,1);
207	    b112 = (Q(+ja)*q1+zl(+ja)*zr1*prop)*amp2_a(1,1,2)
208	         + (Q(+2)*q1+zl(+2)*zr1*prop)*amp2_b(1,1,2);
209	    b221 = (Q(+ja)*q1+zr(+ja)*zl1*prop)*amp2_a(2,2,1)
210	         + (Q(+2)*q1+zr(+2)*zl1*prop)*amp2_b(2,2,1);
211	    b222 = (Q(+ja)*q1+zr(+ja)*zr1*prop)*amp2_a(2,2,2)
212	         + (Q(+2)*q1+zr(+2)*zr1*prop)*amp2_b(2,2,2);
213	    b121 = (Q(+ja)*q1+zl(+ja)*zl1*prop)*amp2_a(1,2,1)
214	         + (Q(+2)*q1+zr(+2)*zl1*prop)*amp2_b(1,2,1);
215	    b122 = (Q(+ja)*q1+zl(+ja)*zr1*prop)*amp2_a(1,2,2)
216	         + (Q(+2)*q1+zr(+2)*zr1*prop)*amp2_b(1,2,2);
217	    b211 = (Q(+ja)*q1+zr(+ja)*zl1*prop)*amp2_a(2,1,1)
218	         + (Q(+2)*q1+zl(+2)*zl1*prop)*amp2_b(2,1,1);
219	    b212 = (Q(+ja)*q1+zr(+ja)*zr1*prop)*amp2_a(2,1,2)
220	         + (Q(+2)*q1+zl(+2)*zr1*prop)*amp2_b(2,1,2);
221	
222	    msq_up = std::real(b111*std::conj(b111))+std::real(b112*std::conj(b112))
223	           + std::real(b221*std::conj(b221))+std::real(b222*std::conj(b222))
224	           + std::real(b122*std::conj(b122))+std::real(b212*std::conj(b212))
225	           + std::real(b121*std::conj(b121))+std::real(b211*std::conj(b211));
226	  }
227	
228	  return;
229	}
